import { type MigrateDownArgs, type MigrateUpArgs, sql } from '@payloadcms/db-postgres'

/**
 * Employee privacy notice (Q-46 / ASVS 8.3.3 / gap G-06, ADR 0018) + selfie retention default (Q-33). Schema part as
 * generated by `payload migrate:create privacy_notice` (snapshot in the .json), written re-runnable, run as
 * <prefix>_owner. ADDITIVE: APK ≤ 0.3.2 and the previous web image keep working against it.
 *
 * 1. `users.privacy_ack_version` (numeric) + `users.privacy_ack_at` (timestamptz): the version of the notice the user
 *    acknowledged and when. Written ONLY by POST /api/v1/me/privacy-ack (field access: read-only). DB guards:
 *    - CHECK `users_privacy_ack_pair`: both NULL or both set; version an integer ≥ 1;
 *    - trigger `users_privacy_ack_guard` (`pk_privacy_ack_guard()`): once set, the version never decreases or goes
 *      back to NULL, and the timestamp of an unchanged version never changes (an acknowledgement is a fact).
 * 2. `audit_logs.action` += 'privacy_ack'.
 * 3. `companies.selfie_retention_months` DEFAULT 12 → 6 (owner decision 2026-10-05). Existing rows are moved by the
 *    data migration `20261005_090100_selfie_retention_6m`.
 * 4. Users list: saved column preferences (`payload_preferences` key `collection-users`) that do not mention the new
 *    column `privacyAck` get it appended (shown), like `*_mc4_list_company_column` did for `company`; a list that
 *    names it (shown or hidden) is left alone.
 */
export async function up({ db }: MigrateUpArgs): Promise<void> {
  await db.execute(sql`
    DO $pk$
    BEGIN
      IF current_user !~ '_owner$' THEN
        RAISE EXCEPTION 'migrations must run as the <prefix>_owner role (current_user=%)', current_user;
      END IF;
    END
    $pk$;

   ALTER TYPE "public"."enum_audit_logs_action" ADD VALUE IF NOT EXISTS 'privacy_ack';
  ALTER TABLE "companies" ALTER COLUMN "selfie_retention_months" SET DEFAULT 6;
  ALTER TABLE "users" ADD COLUMN IF NOT EXISTS "privacy_ack_version" numeric;
  ALTER TABLE "users" ADD COLUMN IF NOT EXISTS "privacy_ack_at" timestamp(3) with time zone;`)

  await db.execute(sql`
    DO $pk$
    BEGIN
      IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'users_privacy_ack_pair') THEN
        ALTER TABLE users ADD CONSTRAINT users_privacy_ack_pair CHECK (
          (privacy_ack_version IS NULL) = (privacy_ack_at IS NULL)
          AND (privacy_ack_version IS NULL OR (privacy_ack_version >= 1 AND privacy_ack_version = trunc(privacy_ack_version)))
        );
      END IF;
    END
    $pk$;

    CREATE OR REPLACE FUNCTION pk_privacy_ack_guard() RETURNS trigger LANGUAGE plpgsql AS $fn$
    BEGIN
      IF OLD.privacy_ack_version IS NOT NULL AND (
           NEW.privacy_ack_version IS NULL
        OR NEW.privacy_ack_version < OLD.privacy_ack_version
        OR (NEW.privacy_ack_version = OLD.privacy_ack_version AND NEW.privacy_ack_at IS DISTINCT FROM OLD.privacy_ack_at)
      ) THEN
        RAISE EXCEPTION 'users.privacy_ack_*: an acknowledgement cannot be withdrawn, lowered or re-dated' USING ERRCODE = '42501';
      END IF;
      RETURN NEW;
    END
    $fn$;

    DROP TRIGGER IF EXISTS users_privacy_ack_guard ON users;
    CREATE TRIGGER users_privacy_ack_guard BEFORE UPDATE ON users FOR EACH ROW EXECUTE FUNCTION pk_privacy_ack_guard();`)

  await db.execute(sql`
    UPDATE "payload_preferences" p
       SET "value" = jsonb_set(p."value", '{columns}', (p."value" -> 'columns') || jsonb_build_array(jsonb_build_object('accessor', 'privacyAck', 'active', true)))
     WHERE p."key" = 'collection-users'
       AND jsonb_typeof(p."value" -> 'columns') = 'array'
       AND NOT EXISTS (SELECT 1 FROM jsonb_array_elements(p."value" -> 'columns') c WHERE c ->> 'accessor' = 'privacyAck');`)
}

/**
 * Rollback (pre-go-live of this release only): drops the guard, the columns and restores DEFAULT 12. The enum value
 * cannot be removed once a `privacy_ack` audit row exists (audit_logs is append-only) → restore the pre-deploy dump
 * instead. Column preferences are left (an unknown accessor is ignored by the admin).
 */
export async function down({ db }: MigrateDownArgs): Promise<void> {
  await db.execute(sql`
  DROP TRIGGER IF EXISTS users_privacy_ack_guard ON users;
  DROP FUNCTION IF EXISTS pk_privacy_ack_guard();
  ALTER TABLE "users" DROP CONSTRAINT IF EXISTS users_privacy_ack_pair;
   ALTER TABLE "audit_logs" ALTER COLUMN "action" SET DATA TYPE text;
  DROP TYPE "public"."enum_audit_logs_action";
  CREATE TYPE "public"."enum_audit_logs_action" AS ENUM('create', 'update', 'status_change', 'deactivate', 'reactivate', 'delete_attempt', 'void', 'view_sensitive', 'login', 'logout', 'login_failed', 'session_revoked', 'role_change', 'role_sync', 'device_register', 'device_revoke', 'number_issued', 'export', 'print', 'sign', 'acknowledge', 'flag_raised', 'flag_reviewed', 'sync_odoo', 'sync_offline', 'period_close', 'period_reopen', 'schema_maintenance', 'email_test', 'approve', 'reject', 'verify', 'acknowledge_delegated', 'access_denied', 'approval_skipped', 'retention_purge', 'import', '2fa_enabled', '2fa_disabled');
  ALTER TABLE "audit_logs" ALTER COLUMN "action" SET DATA TYPE "public"."enum_audit_logs_action" USING "action"::"public"."enum_audit_logs_action";
  ALTER TABLE "companies" ALTER COLUMN "selfie_retention_months" SET DEFAULT 12;
  ALTER TABLE "users" DROP COLUMN IF EXISTS "privacy_ack_version";
  ALTER TABLE "users" DROP COLUMN IF EXISTS "privacy_ack_at";`)
}
